import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int limit = 32000; boolean[] isPrime = new boolean[limit + 1]; Arrays.fill(isPrime, true); isPrime[0] = isPrime[1] = false; for (int p = 2; p * p <= limit; p++) { if (isPrime[p]) { for (int i = p * p; i <= limit; i += p) isPrime[i] = false; } } List<Integer> primes = new ArrayList<>(); for (int p = 2; p <= limit; p++) { if (isPrime[p]) primes.add(p); } String line = br.readLine(); if (line == null) return; int t = Integer.parseInt(line.trim()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int m = Integer.parseInt(st.nextToken()); int n = Integer.parseInt(st.nextToken()); boolean[] range = new boolean[n - m + 1]; Arrays.fill(range, true); if (m == 1) range[0] = false; for (int p : primes) { if (p * p > n) break; int start = (m + p - 1) / p * p; if (start < p * p) start = p * p; for (int j = start; j <= n; j += p) { range[j - m] = false; } } for (int i = 0; i < range.length; i++) { if (range[i]) out.println(i + m); } if (t > 0) out.println(); } out.flush(); out.close(); } }